<?php
if(!defined('ABSPATH')){exit;}
final class Orion_Gemini_Client implements Orion_AI_Provider{
 private string $api_key;private string $model;private int $timeout;private int $max_tokens;public function __construct(string $api_key,string $model,int $timeout=20,int $max_tokens=900){$this->api_key=trim($api_key);$this->model=preg_replace('/[^a-zA-Z0-9._-]/','',trim($model))?:'gemini-3.6-flash';$this->timeout=max(5,min(60,$timeout));$this->max_tokens=max(200,min(4000,$max_tokens));}
 public function chat(array $messages,array $tools=array()):array{$started=microtime(true);if($this->api_key==='')return$this->meta(array('ok'=>false,'error'=>'Google Gemini API key is not configured.'),$started);$url='https://generativelanguage.googleapis.com/v1beta/models/'.rawurlencode($this->model).':generateContent';$response=wp_remote_post($url,array('timeout'=>$this->timeout,'redirection'=>0,'headers'=>array('Content-Type'=>'application/json','x-goog-api-key'=>$this->api_key),'body'=>wp_json_encode($this->body($messages,$tools))));if(is_wp_error($response))return$this->meta(array('ok'=>false,'error'=>'Google Gemini could not be reached: '.sanitize_text_field($response->get_error_message()),'status'=>0),$started);$code=(int)wp_remote_retrieve_response_code($response);$json=json_decode(wp_remote_retrieve_body($response),true);if($code<200||$code>=300){$raw=is_array($json)?trim(wp_strip_all_tags((string)($json['error']['message']??''))):'';$public=match($code){400=>'Google Gemini rejected the request. Check the selected model.',401=>'Google Gemini API key is invalid.',403=>'Google Gemini access is forbidden.',404=>'Google Gemini model was not found.',429=>'Google Gemini is rate limited or its quota is exhausted.',default=>'Google Gemini returned HTTP '.$code.'.'};if($raw!=='')$public.=' Details: '.sanitize_text_field($raw);return$this->meta(array('ok'=>false,'error'=>$public,'status'=>$code),$started);}$parts=$json['candidates'][0]['content']['parts']??array();$text='';$calls=array();foreach($parts as$part){if(isset($part['text']))$text.=(string)$part['text'];if(isset($part['functionCall']['name'])){$api_name=(string)$part['functionCall']['name'];$tool_name=str_contains($api_name,':')?(string)substr($api_name,strrpos($api_name,':')+1):$api_name;$signature=(string)($part['thoughtSignature']??$part['thought_signature']??'');$call=array('id'=>'gemini_'.wp_generate_uuid4(),'type'=>'function','function'=>array('name'=>sanitize_key($tool_name),'arguments'=>wp_json_encode($part['functionCall']['args']??array())),'gemini_function_name'=>$api_name);if($signature!=='')$call['thought_signature']=$signature;$calls[]=$call;}}$message=array('role'=>'assistant','content'=>trim($text));if($calls)$message['tool_calls']=$calls;if($message['content']===''&&!$calls)return$this->meta(array('ok'=>false,'error'=>'Google Gemini returned an empty response.'),$started);$usage=$json['usageMetadata']??array();return$this->meta(array('ok'=>true,'message'=>$message,'usage'=>array('prompt_tokens'=>(int)($usage['promptTokenCount']??0),'completion_tokens'=>(int)($usage['candidatesTokenCount']??0),'total_tokens'=>(int)($usage['totalTokenCount']??0))),$started);}
 private function meta(array $result,float $started):array{$result['provider']='google';$result['model']=$this->model;$result['duration_ms']=(int)round((microtime(true)-$started)*1000);return$result;}
 private function schema(array $schema):array{unset($schema['additionalProperties'],$schema['$schema'],$schema['unevaluatedProperties']);if(isset($schema['properties'])&&is_array($schema['properties']))foreach($schema['properties']as$key=>$value)if(is_array($value))$schema['properties'][$key]=$this->schema($value);if(isset($schema['items'])&&is_array($schema['items']))$schema['items']=$this->schema($schema['items']);if(isset($schema['oneOf'])&&is_array($schema['oneOf']))$schema['oneOf']=array_map(fn($v)=>is_array($v)?$this->schema($v):$v,$schema['oneOf']);if(isset($schema['anyOf'])&&is_array($schema['anyOf']))$schema['anyOf']=array_map(fn($v)=>is_array($v)?$this->schema($v):$v,$schema['anyOf']);return$schema;}
 private function body(array $messages,array $tools):array{$system=array();$contents=array();foreach($messages as$message){$role=(string)($message['role']??'user');if($role==='system'){$system[]=(string)($message['content']??'');continue;}$contents[]=array('role'=>$role==='assistant'?'model':'user','parts'=>array(array('text'=>(string)($message['content']??''))));}$body=array('contents'=>$contents,'generationConfig'=>array('temperature'=>0.2,'maxOutputTokens'=>$this->max_tokens));if($system)$body['systemInstruction']=array('parts'=>array(array('text'=>implode("\n",$system))));if($tools){$decl=array();foreach($tools as$tool){$fn=$tool['function']??array();$decl[]=array('name'=>$fn['name']??'','description'=>$fn['description']??'','parameters'=>$this->schema(is_array($fn['parameters']??null)?$fn['parameters']:array('type'=>'object')));}$body['tools']=array(array('functionDeclarations'=>$decl));$body['toolConfig']=array('functionCallingConfig'=>array('mode'=>'ANY'));}return$body;}
}
